#pragma once
#include "modulation.h"
#include "phrase_conductor.h"
#include <array>
#include <cstddef>
// Single definition of the per-frame GPU constants. The C++ struct and the HLSL cbuffer text live side
// by side so the renderer's main shader and every generated world compile against the same layout.
struct Constants { float resolution[2],time,scene,bass,mid,high,level,percussion,snare,beat,flux,previousScene,transition,logoScale,palette,transitionStyle,tempoPhase,tempoConfidence,audioEnergy,songSection,sectionProgress,dropPulse,onset,kick,beatIndex,barPhase,cuePhase,endingConfidence,directorConfidence,idleLife,cueDensity,masteringProfile,stageLayout,masterBrightness,productionDuty,visualMovement,movementProgress,patternSeed,musicalNovelty,choreographyPhase,identityWeight,identityKind,stanzaProgress,previousPatternSeed,morphPad0,morphPad1,morphPad2,dvdX,dvdY,dvdCorner,dvdControlled,themeBraid,themeFan,themeOrbit,themeAccent; rarestage::show::PhraseFrame phrase{},previousPhrase{}; std::array<std::array<float,4>,40> playPoseData{}; std::array<float,20> playPatternSignals{}; std::array<float,4> bandsA{},bandsB{}; std::array<std::array<float,4>,8> gParam{rarestage::show::NeutralParams()}; std::array<float,4> palA{},palB{},palC{},palD{},palPrev0{},palPrev1{},palPrev2{}; };
static_assert(sizeof(Constants)==1280 && offsetof(Constants,phrase)==224);
static_assert(sizeof(Constants)%16==0,"GPU frame constants must remain 16-byte aligned");

#define RS_FRAME_CBUFFER_HLSL R"(cbuffer Frame : register(b0){float2 resolution;float time;float scene;float bass;float mid;float high;float level;float percussion;float snare;float beat;float flux;float previousScene;float transition;float logoScale;float palette;float transitionStyle;float tempoPhase;float tempoConfidence;float audioEnergy;float songSection;float sectionProgress;float dropPulse;float onset;float kick;float beatIndex;float barPhase;float cuePhase;float endingConfidence;float directorConfidence;float idleLife;float cueDensity;float masteringProfile;float stageLayout;float masterBrightness;float productionDuty;float visualMovement;float movementProgress;float patternSeed;float musicalNovelty;float choreographyPhase;float identityWeight;float identityKind;float stanzaProgress;float previousPatternSeed;float morphPad0;float morphPad1;float morphPad2;float dvdX;float dvdY;float dvdCorner;float dvdControlled;float themeBraid;float themeFan;float themeOrbit;float themeAccent;float4 phraseProgram;float4 phraseShape;float4 oldPhraseProgram;float4 oldPhraseShape;float4 playPoseData[40];float4 playPatternSignals[5];float4 bandsA;float4 bandsB;float4 g_Param[8];float4 g_PalA;float4 g_PalB;float4 g_PalC;float4 g_PalD;float4 g_PalPrev0;float4 g_PalPrev1;float4 g_PalPrev2;})"
